package com.doms.doms.controller;
import com.doms.doms.dto.*;import com.doms.doms.service.DepartmentService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor
public class DepartmentController {private final DepartmentService service;@GetMapping public ResponseEntity<List<LookupResponse>> all(){return ResponseEntity.ok(service.findAll());}@PostMapping public ResponseEntity<LookupResponse> create(@Valid @RequestBody LookupRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") public ResponseEntity<LookupResponse> update(@PathVariable Long id,@Valid @RequestBody LookupRequest r){return ResponseEntity.ok(service.update(id,r));}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
